import{_ as t,o as d,c as o,a2 as s}from"./chunks/framework.C8822HRV.js";const m=JSON.parse('{"title":"sdd CLI reference","description":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial.","frontmatter":{"title":"sdd CLI reference","description":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial.","head":[["meta",{"property":"og:title","content":"sdd CLI reference · sdd"}],["meta",{"property":"og:description","content":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/reference/cli/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"sdd CLI reference · sdd"}],["meta",{"name":"twitter:description","content":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/reference/cli/"}]]},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1793333434000}'),a={name:"reference/cli.md"};function r(n,e,c,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>Binary name: <strong><code>sdd</code></strong>. Install: <strong><a href="https://www.npmjs.com/package/@structured-vibe-coding/cli" target="_blank" rel="noreferrer">@structured-vibe-coding/cli on npm</a></strong> Learn by doing: <a href="./../tutorials/first-change">Start in 10 minutes</a>. One command’s flags: <code>sdd &lt;command&gt; --help</code>.</p><p>Commit <code>.sdd/config.yaml</code>, workflows, templates, <code>protocol.md</code>, <code>memory/</code>, and change packs. Ignore <code>handoff.md</code>, <code>active-context.md</code>, <code>index.db</code>, <code>index.db-journal</code>, <code>index.db-wal</code>, <code>index.db-shm</code>, <code>models/</code>, <code>role-runs/</code>, and <code>&lt;changes_path&gt;/.active</code>. <code>sdd init</code> writes those gitignore rules. On a project that already has <code>.sdd/config.yaml</code>, <code>sdd init</code> without <code>--force</code> appends any missing ignore line and does not rewrite config, memory, or workflows. <code>sdd init --force</code> still refreshes unchanged generated files. A file with no manifest hash is recorded as generated when it matches the bundled file, and left in place when it differs. <code>sdd workflows</code> names bundled workflows that are not copied yet. <code>sdd status</code> prints the change path relative to the repo.</p><hr><h2 id="start-work-which-command" tabindex="-1">Start work: which command? <a class="header-anchor" href="#start-work-which-command" aria-label="Permalink to &quot;Start work: which command?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Command</th></tr></thead><tbody><tr><td>Everyday / ad-hoc title (bug, small feature, spike)</td><td><strong><code>sdd new &quot;Title&quot;</code></strong> (optional <code>-w hotfix|feature|…</code>)</td></tr><tr><td>Item from product backlog after greenfield (<code>F-001</code>)</td><td><strong><code>sdd backlog start F-001</code></strong></td></tr><tr><td>New product discovery (vision → backlog)</td><td><strong><code>sdd greenfield &quot;One-line idea&quot;</code></strong></td></tr></tbody></table><p><code>sdd new</code> and <code>sdd backlog start</code> both open a <strong>change pack</strong>. The difference is the <strong>source</strong>: free-form title vs backlog id. <code>-w feature</code> is a <strong>workflow pack name</strong>, not the same as <code>sdd backlog</code> / the old <code>sdd feature</code> alias.</p><p><code>sdd setup</code> is the first-time path. On a terminal it walks folder, workflow, host, roles, model, a check, and an optional first change. Enter initializes the folder, keeps the <code>feature</code> workflow, skips the host, and writes planner, architect, and builder when no role file exists yet. Each new duty file lists the stages of the workflow you pass with <code>-w</code>. Come back to one piece with <code>sdd setup --step model</code> (also <code>folder</code>, <code>workflow</code>, <code>host</code>, <code>roles</code>, <code>check</code>, or <code>start</code>). <code>sdd setup --yes</code> keeps the short path: the three duties when the roles folder is empty, a host only with <code>--ai</code>, and no model file. What a role and a duty are, why they help, and the setup for each workflow are in <a href="./../guides/roles">Roles and duties</a>. <code>sdd go &quot;I want to build this&quot;</code> opens the change and runs the role for the current stage. That role asks the questions in its <code>ask_human_when</code> list, one at a time. Answer with <code>sdd go --answer &quot;...&quot;</code>. On a terminal, <code>sdd go</code> asks in place. When the draft is written, the guide moves to the next stage and hands the work to the role that lists it. Optional clarify and brainstorm stages are skipped. A hard gate that needs you stops and says so. The role does not sign it. A role whose <code>never</code> list says <code>write product code</code> can write only inside the change pack. Push, a pull request, and merge stay refused.</p><hr><h2 id="i-want-to" tabindex="-1">I want to… <a class="header-anchor" href="#i-want-to" aria-label="Permalink to &quot;I want to…&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Command</th></tr></thead><tbody><tr><td>Set up this project</td><td><code>sdd setup</code></td></tr><tr><td>Set up one piece</td><td><code>sdd setup --step model</code></td></tr><tr><td>Set up and name the AI host</td><td><code>sdd init --here --ai copilot</code></td></tr><tr><td>Set up without any AI host</td><td><code>sdd init --here --no-agent</code></td></tr><tr><td>Build something with the roles</td><td><code>sdd go &quot;I want to build this&quot;</code></td></tr><tr><td>Check setup</td><td><code>sdd doctor</code></td></tr><tr><td>Start small work</td><td><code>sdd new &quot;Title&quot; -w hotfix -y</code></td></tr><tr><td>Start mid-size work (workflow pack)</td><td><code>sdd new &quot;Title&quot; -w feature -y</code></td></tr><tr><td>Start a new product</td><td><code>sdd greenfield &quot;One-line idea&quot;</code></td></tr><tr><td>See product backlog</td><td><code>sdd backlog list</code></td></tr><tr><td>Build backlog item</td><td><code>sdd backlog start F-001</code></td></tr><tr><td>See where I am</td><td><code>sdd status</code></td></tr><tr><td>Sync recorded checks to local HEAD</td><td><code>sdd sync &lt;change&gt;</code></td></tr><tr><td>Import measured agent token usage</td><td><code>sdd metrics import &lt;session-log&gt;</code></td></tr><tr><td>Report phase time, tokens, and cost</td><td><code>sdd report</code></td></tr><tr><td>Report every change that has metrics</td><td><code>sdd report --all</code></td></tr><tr><td>Print the one-change cost report</td><td><code>sdd cost</code></td></tr><tr><td>Move to next step</td><td><code>sdd next</code></td></tr><tr><td>Finish work</td><td><code>sdd complete</code></td></tr><tr><td>Check the change works</td><td><code>sdd verify</code></td></tr><tr><td>Improve current notes</td><td><code>sdd refine</code></td></tr><tr><td>Get help from AI now</td><td><code>sdd agent</code></td></tr><tr><td>Don’t open AI this time</td><td>add <code>--no-agent</code></td></tr></tbody></table><hr><h2 id="all-commands" tabindex="-1">All commands <a class="header-anchor" href="#all-commands" aria-label="Permalink to &quot;All commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th><th>When</th></tr></thead><tbody><tr><td><code>sdd setup</code></td><td>Walk setup on a terminal. Enter writes the folder, the feature workflow, and the three duties when no role file exists. <code>--yes</code> keeps that short path. <code>--step</code> runs one piece</td><td>First time, or one missing piece</td></tr><tr><td><code>sdd go &quot;title&quot;</code></td><td>Open a change, ask each role&#39;s questions, draft each required file under its own headings, and hand off to the next role</td><td>After setup</td></tr><tr><td><code>sdd go --answer &quot;...&quot;</code></td><td>Give the answer the current role is waiting for</td><td>When a role asks</td></tr><tr><td><code>sdd init</code></td><td>Create sdd files + one AI setup</td><td>Once per app</td></tr><tr><td><code>sdd init --force</code></td><td>Merge current defaults into supported config; refresh only unchanged SDD-generated workflows/templates and agent files. A file with no manifest hash is recorded as generated when it matches the bundled file</td><td>Upgrades</td></tr><tr><td><code>sdd new &quot;title&quot;</code></td><td>Start a change pack from a free-form title</td><td>Everyday work</td></tr><tr><td><code>sdd new … -w &lt;pack&gt;</code></td><td>Choose path (hotfix, feature, …)</td><td>You know the path</td></tr><tr><td><code>sdd new … -y</code></td><td>Skip confirm prompts</td><td>Scripts / CI</td></tr><tr><td><code>sdd greenfield &quot;idea&quot;</code></td><td>New product plan path</td><td>Empty / MVP product</td></tr><tr><td><code>sdd backlog list</code></td><td>Show F-001… product backlog</td><td>After greenfield</td></tr><tr><td><code>sdd backlog start F-001</code></td><td>Start work from backlog id</td><td>Build product items</td></tr><tr><td><code>sdd feature list|start</code></td><td><strong>Alias</strong> for <code>sdd backlog …</code> (compat)</td><td>Old scripts</td></tr><tr><td><code>sdd status</code></td><td>Progress (<strong>no</strong> AI)</td><td>Anytime</td></tr><tr><td><code>sdd status --list</code></td><td>All open changes</td><td>Several PRs</td></tr><tr><td><code>sdd sync &lt;change&gt;</code></td><td>Update recorded verification SHAs to local <code>git rev-parse HEAD</code></td><td>After a new commit</td></tr><tr><td><code>sdd metrics import &lt;session-log&gt;</code></td><td>Import measured Claude Code or Codex JSONL, a Grok <code>usage.json</code>, or a Grok session directory into the active change; use <code>--change &lt;id&gt;</code> for another change</td><td>Review token use</td></tr><tr><td><code>sdd report</code></td><td>Print active time, human wait, measured tokens, and cost for the active change. Use <code>--change &lt;id&gt;</code> to select one change.</td><td>After metrics exist</td></tr><tr><td><code>sdd report --all</code></td><td>Print that report for every change that has a metrics.json, sorted by first phase start.</td><td>Compare changes</td></tr><tr><td><code>sdd cost</code></td><td>Print the same one-change report as <code>sdd report</code>, including the same cost figures. Use <code>--change &lt;id&gt;</code> to select one change.</td><td>Check cost</td></tr><tr><td><code>sdd next</code></td><td>Advance one stage</td><td>Step done</td></tr><tr><td><code>sdd next --force</code></td><td>Bypass checks</td><td>Emergency only</td></tr><tr><td><code>sdd skip &lt;stage&gt; -r &quot;…&quot;</code></td><td>Skip a stage</td><td>Not needed</td></tr><tr><td><code>sdd use &lt;workflow&gt;</code></td><td>Switch path mid-flight</td><td>Scope changed</td></tr><tr><td><code>sdd gate approve|waive|fail</code></td><td>Approve / waive / fail a gate</td><td>Enterprise gates</td></tr><tr><td><code>sdd verify</code></td><td>Run the stage&#39;s <code>verify.commands</code>; PASS (exit 0) only if at least one ran and all exited 0. FAIL (exit 1) if any failed. NOT RUN (exit 1) on a stage without a verify step or with <code>commands: []</code></td><td>Before complete</td></tr><tr><td><code>sdd verify --no-run</code></td><td>Checklist only — records NOT RUN, exits 1</td><td>Manual testing</td></tr><tr><td><code>sdd complete</code></td><td>Mark done (greenfield also saves to <code>memory/</code>)</td><td>Finished</td></tr><tr><td><code>sdd refine [stage]</code></td><td>Improve notes</td><td>Spec quality</td></tr><tr><td><code>sdd refine --analyze</code></td><td>Report only</td><td>Audit</td></tr><tr><td><code>sdd context</code></td><td>Focused code slices under a token budget</td><td>Implement</td></tr><tr><td><code>sdd search &quot;&lt;query&gt;&quot;</code></td><td>Keyword search (<code>--scope code|specs|memory</code>, optional <code>--budget</code>). <code>provider: mcp</code> asks one MCP source and falls back to this keyword search.</td><td>Find a symbol without opening AI</td></tr><tr><td><code>sdd mcp sources list/add/test/remove</code></td><td>External MCPs <strong>sdd calls</strong></td><td>Design system / AST / org lib</td></tr><tr><td><code>sdd mcp fetch</code></td><td>Pull matching sources for current stage</td><td>Enrich handoff / implement</td></tr><tr><td><code>sdd agent</code></td><td>Refresh brief + open AI</td><td>Anytime</td></tr><tr><td><code>sdd role</code></td><td>Create, list, and run a product role. <code>sdd role create &lt;name&gt; --template software/developer</code> copies a shipped role</td><td>One job and one stop</td></tr><tr><td><code>sdd team init --template software</code></td><td>Write <code>.sdd/team.yaml</code>, that template&#39;s roles, and <code>routing.yaml</code> when the template has one. Also <code>solo</code> and <code>research</code>. Does not overwrite</td><td>Model a team</td></tr><tr><td><code>sdd team show</code></td><td>Print bots, human approvers, the rooms commit switch, and the branch pattern</td><td>See the team</td></tr><tr><td><code>sdd team check</code></td><td>Read <code>team.yaml</code>, then reject a literal secret in <code>.sdd/models.yaml</code>. A missing models file is allowed. An env-var name is allowed</td><td>Before a team runs</td></tr><tr><td><code>sdd models show</code></td><td>Print each model and which work type uses it</td><td>See the pick</td></tr><tr><td><code>sdd models which --work-type draft</code></td><td>Print the model for one work type. <code>--bot</code> beats <code>--stage</code>, which beats <code>--role</code></td><td>Explain one slot</td></tr><tr><td><code>sdd graph --epic &lt;key&gt;</code></td><td>Print which stories can run together and which must wait</td><td>Epic planning</td></tr><tr><td><code>sdd branch &lt;name&gt;</code></td><td>Create that story branch from <code>main</code></td><td>Start one story</td></tr><tr><td><code>sdd pr</code></td><td>Push the change branch and open a pull request</td><td>Story is ready</td></tr><tr><td><code>sdd checkout &lt;id&gt;</code></td><td>Switch active change</td><td>Multi-PR</td></tr><tr><td><code>sdd workflows</code></td><td>List project workflows, name bundled workflows that are not copied yet, and print cl100k token counts for each workflow file and artifact</td><td>Discover</td></tr><tr><td><code>sdd help</code></td><td>Short overview</td><td>First run</td></tr><tr><td><code>sdd doctor</code></td><td>Health check</td><td>Stuck / setup</td></tr></tbody></table><h3 id="greenfield-backlog" tabindex="-1">Greenfield / backlog <a class="header-anchor" href="#greenfield-backlog" aria-label="Permalink to &quot;Greenfield / backlog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td><code>sdd greenfield [&quot;idea&quot;]</code></td><td>Asks for idea if you omit it; supports <code>--no-agent</code></td></tr><tr><td><code>sdd backlog start F-001</code></td><td><code>-w</code> can override the backlog workflow; supports <code>--no-agent</code></td></tr><tr><td><code>sdd backlog list</code></td><td>Never opens the AI</td></tr><tr><td><code>sdd feature …</code></td><td>Same as <code>sdd backlog …</code>; prefer <strong>backlog</strong> in new docs and scripts</td></tr></tbody></table><hr><h2 id="about-the-ai-opening" tabindex="-1">About the AI opening <a class="header-anchor" href="#about-the-ai-opening" aria-label="Permalink to &quot;About the AI opening&quot;">​</a></h2><p>Most process commands refresh a short handoff and may open your AI. <strong>Never open AI:</strong> <code>status</code>, <code>report</code>, <code>cost</code>, <code>search</code>, <code>init</code>, <code>workflows</code>, <code>context</code>, <code>backlog list</code>, <code>help</code>, <code>doctor</code>.</p><p>Turn AI off for one command: <code>--no-agent</code> or <code>SDD_NO_AGENT=1</code>. Set up with no AI host at all: <code>sdd init --here --no-agent</code>. This installs no host files and no <code>AGENTS.md</code>, never prompts, and leaves nothing for commands to launch.</p><p>Phase timing and token metrics are enabled by default. Disable collection in <code>.sdd/config.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metrics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  exclude</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span></code></pre></div><p><code>metrics.exclude</code> lists repo-relative prefixes. Import refuses to read a session log under an excluded prefix. The default is <code>[]</code>.</p><p>When metrics are disabled, <code>sdd report</code> and <code>sdd cost</code> print <code>Metrics are disabled</code> and exit 0.</p><p>Session imports store measured token counts, request IDs, phase names, timestamps, and, for Grok, the model id. The session-log path and prompt/response content are not stored. A Grok usage.json stores one request per turn and model. inputTokens in that file includes cache reads; sdd stores the uncached remainder as input and the cache buckets separately. The model id is stored. Server cost ticks are not imported. When a sibling events.jsonl has turn_started for that turn, that timestamp is the request time; otherwise the turn endedAt is used.</p><p>Tools without session logs can use a local proxy that the operator runs; sdd does not read proxy logs in this version.</p><p><code>.sdd/prices.yaml</code> holds USD rates per one million tokens and <code>usd_to_inr</code> (default 84). <code>sdd init</code> writes it only when missing. Cost uses <code>models.&lt;model&gt;</code> when the request has a model id and that key exists, otherwise <code>models.&lt;provider&gt;</code>, otherwise <code>models.default</code>. If the file is missing, every cost is <code>n/a</code> and the report says <code>prices.yaml is missing</code>. Costs are not written into <code>metrics.json</code>.</p><p>If a change has no measured requests, the report adds one <code>estimated (handoff code points / 4)</code> row from <code>.sdd/handoff.md</code> and labels it as an estimate, not a model tokenizer. This version does not include a BPE tokenizer.</p><p>Search, context packing, and the handoff retrieved section count tokens with <code>cl100k_base</code>. That count is separate from the report estimate.</p><p><code>sdd workflows</code> prints those same cl100k counts for every copied workflow. The workflow line counts the workflow file. Each artifact line counts the template that stage copies. A missing template prints <code>missing</code>. When a change is active, a <code>Change</code> section counts the artifact files in that change. A file that has not been written prints <code>not written</code>. This view has no dollar amount.</p><p>Embeddings are off by default. Set <code>embeddings: true</code> in <code>.sdd/search.yaml</code> to download <code>BAAI/bge-small-en-v1.5</code> once into <code>.sdd/models/</code> and rank with hybrid fusion. A missing model falls back to keyword search.</p><p><code>provider: mcp</code> is also off unless you set it. <code>sdd search</code> then calls one source from <code>.sdd/mcp.yaml</code> with the query and the scope. A missing or broken source falls back to keyword search. Handoff stays on the built-in index. The language matrix is <a href="./search-providers">Search providers</a>.</p><p>Related change specs and memory pages can be packed as a short extractive summary. The active change and code stay full. The keyword index is unchanged. Repeated searches are cached in <code>.sdd/index.db</code>, and search text does not gain a cache banner.</p><p><code>sdd sync &lt;change&gt;</code> only updates local change metadata and SDD-marked verification output. It does not create a commit or update a hosted PR body; verify checks recorded SHA/count references before reporting PASS. Run the relevant checks on the new commit before treating a sync as fresh test evidence.</p><hr><h2 id="sdd-role" tabindex="-1">sdd role <a class="header-anchor" href="#sdd-role" aria-label="Permalink to &quot;sdd role&quot;">​</a></h2><p>A role file at <code>.sdd/roles/&lt;name&gt;.md</code> is the profile a product repo can commit. It is not a host stub from <code>sdd agents install</code>. A shipped template can fill <code>owns</code>, <code>inputs</code>, <code>outputs</code>, <code>collaborates</code>, <code>reviews</code>, <code>approvers</code>, <code>never</code>, <code>ask_human_when</code>, <code>skills</code>, <code>rules</code>, and <code>goals</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> team</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> software</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> team</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> role</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> builder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> software/developer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> role</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analyst</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Analyst&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --job</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Write the reading&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> intent,design</span></span></code></pre></div><p><code>--stages</code> lists stage ids from the workflow you pass to <code>sdd new -w</code>. <code>sdd role route</code> uses that list for the active stage. <code>team-software</code> stays one stage pack you can name with <code>-w</code>. <code>sdd role edit &lt;name&gt; --stages ...</code> replaces the list.</p><p><code>sdd role context &lt;name&gt;</code> prints that role&#39;s context. With no saved context, the role writes one from the repo, the role name, and any knowledge already saved. <code>sdd role context &lt;name&gt; --text &quot;...&quot;</code> saves the context you wrote. <code>sdd role context &lt;name&gt; --knowledge &quot;...&quot;</code> saves optional knowledge. <code>sdd role context &lt;name&gt; --generate</code> writes a new context from the repo, the role name, and that knowledge. <code>sdd role run</code> includes the saved context. A context that does not fit the run budget is left out of that run.</p><p><code>software</code> ships product-manager, architect, product-owner, dev-lead, developer, and qa. <code>solo</code> ships one developer. <code>research</code> ships one researcher. <code>developer</code> alone is ambiguous. Pass <code>software/developer</code> or <code>solo/developer</code>. Init writes nothing when <code>.sdd/team.yaml</code>, <code>.sdd/routing.yaml</code> (when the template ships one), or one of the template&#39;s role files already exists. A human approver whose name matches <code>git config user.name</code> is marked <code>(you)</code>. The rooms commit switch is stored. Shipped templates set it to true, so a new team commits rooms unless that team sets <code>rooms.commit</code> to false. The branch pattern includes <code>{bot}</code>.</p><p><code>sdd role route</code> prints the role, the reason, and the rule for one item. With no flags it uses the active change. Rules in <code>.sdd/routing.yaml</code> are tried first. Then one role whose <code>owns</code> list names the artifact, or whose <code>skills</code> list names the skill. Then one role whose <code>stages</code> list contains the stage id. Then the active workflow stage&#39;s <code>owner</code>, when that role file exists. No match prints <code>Ask the human.</code> Two roles that own the item, or two roles that list the stage, also print <code>Ask the human.</code> With no <code>.sdd/models.yaml</code>, this command does not call a model. When that file exists, only the no-rule ask may call a decider. A matched rule, one owner, a stage list, a stage owner, two owners, or two stage lists do not. <code>sdd team init</code> does not write <code>models.yaml</code>. Model overrides live in that file, not in <code>team.yaml</code>. <code>sdd role queue</code> prints each bot inbox at <code>.sdd/agents/&lt;name&gt;/inbox.jsonl</code>. <code>sdd role take</code> writes one active item onto a bot of that role that is under its <code>wip</code> limit and under <code>role_wip</code> when the team sets one. A bot at either limit is not given another item. A handoff appends the same typed note to both inboxes. Those notes do not count toward the limit.</p><p>A role file at <code>.sdd/roles/&lt;name&gt;.md</code> is still not a host stub. The four host stubs (<code>sdd</code>, <code>sdd-planner</code>, <code>sdd-implementer</code>, <code>sdd-reviewer</code>) each state what they own, what they never do, what they check, and when they ask. <code>sdd role run</code> stops in plain language before it writes a file. Allow once writes only the named file. Always allow remembers that file and those inputs for that role, and only while git HEAD stays the same. With no HEAD, the remembered inputs still apply. <code>sdd role connector read github-issue &lt;number&gt;</code> prints that issue&#39;s number, title, and state. A missing issue is reported and is not invented. The connector name <code>x</code> is refused. Any other connector, and any action other than that read, does not run in this slice. <code>sdd role routine run &lt;role&gt; &lt;name&gt;</code> repeats a read saved on the role file. A routine cannot write a QA result. Edit, pin, hide, and duplicate keep that saved read and do not run it. Hide does not pause it.</p><p><code>sdd team signoff --note &quot;...&quot;</code> records the person named by <code>git config user.name</code> when that name is listed under humans in <code>.sdd/team.yaml</code>. It writes <code>reviews/&lt;stage&gt;-&lt;sha&gt;.md</code> on the active change and appends one line to <code>decisions.md</code>. A hard gate whose approvers include <code>human</code> does not open for <code>sdd next</code> until that file matches the current HEAD. <code>sdd gate waive</code> still opens it. <code>sdd role decide --note &quot;...&quot;</code> appends an unsigned decision request and does not approve a gate.</p><p><code>sdd fact set &lt;key&gt; &lt;value&gt;</code> appends one line to <code>.sdd/facts.jsonl</code>. <code>sdd fact get</code> prints the newest value for that key, and <code>sdd fact list</code> prints one newest line per key. A value that repeats a constitution bullet and says to ignore, skip, or override it is not written. <code>sdd role memory &lt;bot&gt;</code> prints that bot&#39;s memory. <code>sdd role lesson add &lt;bot&gt; &quot;...&quot;</code> appends a lesson a person wrote, and the next run for that bot includes it. <code>sdd team migrate</code> moves memory and lessons from <code>.sdd/role-runs/memory/</code> into <code>.sdd/agents/&lt;name&gt;/</code> and prints each move. A run named as a bot uses that brain and a step loop. A run with no team file stays one author call, then critique and revision when a section is in review.</p><p><code>sdd role room</code> prints the active change&#39;s room for the active stage, <code>.sdd/rooms/&lt;change&gt;/&lt;stage&gt;.jsonl</code>. <code>sdd role room &lt;change-id&gt;</code> prints that change. <code>sdd role room --stage &lt;stage&gt;</code> and <code>sdd role room --stage=&lt;stage&gt;</code> print that stage. <code>sdd role room post &quot;&lt;line&gt;&quot;</code> appends one line a person wrote. On <code>post</code>, <code>--change</code> and <code>--stage</code> select the file. An objection without a cite is refused. <code>sdd role review</code> runs one round for the stage owner and the roles in <code>collaborates</code>, at most <code>limits.room_rounds</code> rounds and otherwise 2. The round prompt includes the critique lines, and the owner also gets the revision lines when an objection is open. A finished round appends one <code>room</code> line to <code>decisions.md</code> with who agreed, the SHA, and the open cites. A room that is still open at the cap also appends <code>decision-needed</code>. <code>rooms.commit: false</code> adds <code>rooms/</code> to <code>.sdd/.gitignore</code> when the team file is loaded. <code>rooms.commit: true</code> removes that line. The stage file is not rewritten, and an open room does not block <code>sdd next</code>.</p><p>A run named as a bot can read a file, search, ask for code context, run one allowlisted check, write a file, and commit. <code>run_check</code> runs a command only when that exact string is on the active stage&#39;s <code>verify.commands</code> or in <code>.sdd/tools.yaml</code>. The command runs in a temporary worktree at HEAD, and the result is <code>changes/&lt;id&gt;/evidence/&lt;sha&gt;.json</code>. A check, a done line, or a room line that says the work passed, works, or is fixed is refused unless that file&#39;s latest run exited 0 at the current HEAD. On a stage that lists verify commands, an agree needs the same cite. A commit runs only when the current branch is already <code>team.branch</code> for that bot and change. Push, a pull request, and merge are refused and do not run git. A name that is not a bot still only applies <code>write_file</code>.</p><p><code>sdd role messaging off</code> stops a handoff before any model call. <code>sdd role handoff &lt;from&gt; --to &lt;role&gt; --change &lt;id&gt; --section &lt;id&gt; --task &quot;...&quot;</code> writes the same handoff record on both conversations and calls only the receiver. <code>sdd role group --change &lt;id&gt;</code> lists accepted owners. <code>sdd role network</code> prints one service, a connection with the lead absent, or asks the lead for a plan of depth at most 2. Nobody writes until <code>sdd role network accept</code>. <code>sdd role network run</code> runs a node only after its prerequisites, and the parent stays open until every node has a result.</p><p>A local adapter shows the three passes. It reads <code>{&quot;roleId&quot;,&quot;prompt&quot;}</code> and writes one JSON object. It does not call a network. A decide command is separate. Set <code>SDD_DECIDE_MODEL</code> to a command that reads <code>{&quot;mode&quot;:&quot;decide&quot;,&quot;state&quot;,&quot;question&quot;,&quot;options&quot;}</code> and writes <code>{&quot;pick&quot;,&quot;probs&quot;}</code>. The example adapter stays a reason command.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SDD_ROLE_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node docs/examples/role-model.mjs&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> role</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> builder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --change</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --section</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sectio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span></span></code></pre></div><p>A prompt that contains <code>changed must list every gap cite.</code> is the revision. Its <code>text</code> is <code>Revised draft.</code>, <code>changed</code> lists every gap cite, and <code>action</code> is <code>write_file</code> on <code>notes/draft.md</code>. A prompt that contains <code>Draft:</code> and <code>Cite:</code> is the critique. Its <code>text</code> is <code>Checked the draft.</code>, and the gap <code>text</code> is <code>The draft misses this check.</code> The gap cite is the first check id under <code>Check ids:</code>. Any other prompt is the author pass and returns <code>Draft from the local example.</code> The <code>write_file</code> action stops for Allow once, Always allow, or Deny.</p><h2 id="epic-stories" tabindex="-1">Epic stories <a class="header-anchor" href="#epic-stories" aria-label="Permalink to &quot;Epic stories&quot;">​</a></h2><p><code>sdd new --epic issue-37 --story S-001</code> records one vertical slice. <code>--depends S-001</code> names a story that must be completed first. <code>sdd graph --epic issue-37</code> prints the waves. Stories in one wave can run at the same time. A later wave waits. <code>sdd branch &lt;name&gt;</code> creates that branch from <code>main</code> when every dependency is completed. <code>sdd pr</code> pushes it and opens the pull request. The body does not close an issue unless <code>--closes</code> is set. <code>sdd backlog</code> remains the greenfield <code>F-001</code> list.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../guides/everyday-loop">Everyday loop</a></li><li><a href="./../guides/greenfield">Greenfield</a></li><li><a href="./../guides/agents">AI setup</a></li><li><a href="./../guides/mcp">MCP sources</a></li><li><a href="./../guides/code-context">Code context</a></li></ul>`,55)])])}const u=t(a,[["render",r]]);export{m as __pageData,u as default};
